BEGIN;

UPDATE branch_settings
SET tax_policy_json = tax_policy_json || '{"calculationMode":"NONE","rateBasisPoints":0,"roundingMode":"HALF_UP","allowPartialPayments":true,"manualDiscountApprovalThresholdMinor":50000,"cashVarianceThresholdMinor":5000,"cashMovementApprovalThresholdMinor":100000}'::jsonb
WHERE tenant_id='10000000-0000-4000-8000-000000000001';

ON CONFLICT(id) DO NOTHING;
ON CONFLICT(id) DO NOTHING;

UPDATE appointments SET checkout_ready=true,status='COMPLETED'
WHERE tenant_id='10000000-0000-4000-8000-000000000001' AND id='70000000-0000-4000-8000-000000000035';

ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

ON CONFLICT DO NOTHING;

SELECT tenant_id,id,version,pricing_snapshot_json,'DETERMINISTIC_SEED','30000000-0000-4000-8000-000000000016','seed:sprint6'
FROM pos_orders o WHERE o.id::text LIKE 'a4000000-%' ON CONFLICT DO NOTHING;





COMMIT;
